            groups: [],
            meta: {
                description: 'Description',
                legend: [
                    { id: 'async-entry', kind: 'async', label: 'Fire and forget', useLabelAsDefault: true },
                    { id: 'service-entry', label: 'Order service', role: 'focal' },
